data.code:
param recoveryVaultName string
param location string = resourceGroup().location

resource recoveryVault 'Microsoft.RecoveryServices/vaults@2023-04-01' existing = {
  name: recoveryVaultName
}

resource replicationPolicy 'Microsoft.RecoveryServices/vaults/replicationPolicies@2023-04-01' = {
  name: '${recoveryVaultName}/default-policy'
  properties: {
    providerSpecificInput: [
      {
        instanceType: 'A2AContainer'
        recoveryPointObjectiveInMinutes: 30
        applicationConsistentSnapshotFrequencyInMinutes: 60
        multiVmSyncEnabled: true
      }
    ]
  }
}
